CREATE TABLE "design_prototypes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code() CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  "project_id" bigint NOT NULL,
  "title" text NOT NULL,
  "summary" text NOT NULL DEFAULT '',
  "status" text NOT NULL DEFAULT 'draft',
  "current_revision" integer NOT NULL DEFAULT 1,
  "owner_principal_id" bigint NOT NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  CONSTRAINT "ck_design_prototypes_status" CHECK ("status" IN ('draft', 'ready', 'archived')),
  CONSTRAINT "ck_design_prototypes_current_revision" CHECK ("current_revision" > 0)
);
--> statement-breakpoint
CREATE TABLE "design_prototype_revisions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code() CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  "prototype_id" bigint NOT NULL,
  "revision" integer NOT NULL,
  "html_content" text NOT NULL,
  "change_summary" text NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" text NOT NULL,
  CONSTRAINT "ck_design_prototype_revisions_revision" CHECK ("revision" > 0)
);
