CREATE TABLE "design_prototype_requirements" (
  "prototype_id" bigint NOT NULL,
  "requirement_id" bigint NOT NULL,
  CONSTRAINT "design_prototype_requirements_pk" PRIMARY KEY ("prototype_id", "requirement_id")
);
